#include <bits/stdc++.h>

using namespace std;

int u[500], b, x;

int main() {
    for (int i = 1; i <= 6; ++i) {
        scanf("%d", &x);
        u[x]++;

        if (u[x] == 4) {
            b = 1;
            u[x] -= 4;
        }
    }

    if (!b) {
        cout << "Alien";
        return 0;
    }

    for (int i = 0; i <= 10; ++i) {
        if (u[i] == 2) {
            cout << "Elephant";
            return 0;
        }

        if (u[i]) {
            cout << "Bear";
            return 0;
        }
    }

    return 0;
}

